        ["session.start"] = new HashSet<string> { "text", "audio" },
        ["user.said"] = new HashSet<string> { "text" },
        ["tool.result"] = new HashSet<string> { "text", "audio" },
        ["session.end"] = new HashSet<string> { "text", "audio" },
        ["session.resumed"] = new HashSet<string> { "text", "audio" },
        ["agent.say"] = new HashSet<string> { "text" },
        ["tool.call"] = new HashSet<string> { "text", "audio" },
        ["agent.clear"] = new HashSet<string> { "text", "audio" },
        ["session.resume"] = new HashSet<string> { "text", "audio" },
    };

    /// <summary>Frames that do not count towards <c>received</c>, whatever they carry; every other frame with a session_id counts, also one of an unknown type.</summary>
    public static readonly IReadOnlySet<string> Uncounted = new HashSet<string> { "error", "session.start", "session.resumed", "session.resume", "audio" };

    /// <summary>The values Sent lists today; it may add more, so a runtime treats others as it would the fallback.</summary>
    public static readonly IReadOnlyList<string> PartyKinds = new[] { "user", "number", "conference", "agent", "anonymous" };

    /// <summary>The values Sent lists today; it may add more, so a runtime treats others as it would the fallback.</summary>
    public static readonly IReadOnlyList<string> SessionEndReasons = new[] { "caller_hung_up", "agent_hung_up", "transferred", "max_duration", "agent_unreachable", "balance_exhausted", "voice_disabled", "failed" };

    private static readonly JsonSerializerOptions Options = new()
    {
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        // Frames are read by machines over a WebSocket: a + or a < stays itself rather than a \u escape.
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    /// <summary>The frame a JSON object carries. Throws FrameException when it breaks the protocol.</summary>
    public static Frame Decode(JsonNode? data)
    {
        if (data is not JsonObject obj || StringOf(obj["type"]) is not string type)
            throw new FrameException("a frame is a JSON object with a string type");
        switch (type)
        {
            case "connection.ready":
                CheckConnectionReady(obj, type);
                return Build<ConnectionReady>(obj);
            case "connection.draining":
                CheckConnectionDraining(obj, type);
                return Build<ConnectionDraining>(obj);
            case "ping":
                CheckPing(obj, type);
                return Build<Ping>(obj);
            case "error":
                CheckErrorFrame(obj, type);
                return Build<ErrorFrame>(obj);
            case "session.start":
                CheckSessionStart(obj, type);
                return Build<SessionStart>(obj);
            case "user.said":
                CheckUserSaid(obj, type);
                return Build<UserSaid>(obj);
            case "tool.result":
                CheckToolResult(obj, type);
                return Build<ToolResult>(obj);
            case "session.end":
                CheckSessionEnd(obj, type);
                return Build<SessionEnd>(obj);
            case "session.resumed":
                CheckSessionResumed(obj, type);
                return Build<SessionResumed>(obj);
            case "agent.say":
                CheckAgentSay(obj, type);
                return Build<AgentSay>(obj);
            case "tool.call":
                CheckToolCall(obj, type);
                return Build<ToolCall>(obj);
            case "agent.clear":
                CheckAgentClear(obj, type);
                return Build<AgentClear>(obj);
            case "session.resume":
                CheckSessionResume(obj, type);
                return Build<SessionResume>(obj);
            case "pong":
                CheckPong(obj, type);
                return Build<Pong>(obj);
            default:
                return new UnknownFrame(obj);
        }
    }

    /// <summary>The frame a JSON text carries. Throws FrameException when it is not JSON or breaks the protocol.</summary>
    public static Frame Decode(string json)
    {
        JsonNode? node;
        try
        {
            node = JsonNode.Parse(json);
        }
        catch (JsonException error)
        {
            throw new FrameException($"not JSON: {error.Message}");
        }
        return Decode(node);
    }

    /// <summary>The JSON object to send for a frame, with type first. Throws FrameException when it breaks the protocol.</summary>
    public static JsonObject Encode(Frame frame)
    {
        if (frame is UnknownFrame unknown)
            return (JsonObject)unknown.Fields.DeepClone();
        var data = new JsonObject { ["type"] = frame.Type };
        var fields = (JsonObject)JsonSerializer.SerializeToNode(frame, frame.GetType(), Options)!;
        foreach (var (key, value) in fields.ToList())
        {
            fields.Remove(key);
            data[key] = value;
        }
        switch (frame.Type)
        {
            case "connection.ready":
                CheckConnectionReady(data, frame.Type);
                break;
            case "connection.draining":
                CheckConnectionDraining(data, frame.Type);
                break;
            case "ping":
                CheckPing(data, frame.Type);
                break;
            case "error":
                CheckErrorFrame(data, frame.Type);
                break;
            case "session.start":
                CheckSessionStart(data, frame.Type);
                break;
            case "user.said":
                CheckUserSaid(data, frame.Type);
                break;
            case "tool.result":
                CheckToolResult(data, frame.Type);
                break;
            case "session.end":
                CheckSessionEnd(data, frame.Type);
                break;
            case "session.resumed":
                CheckSessionResumed(data, frame.Type);
                break;
            case "agent.say":
                CheckAgentSay(data, frame.Type);
                break;
            case "tool.call":
                CheckToolCall(data, frame.Type);
                break;
            case "agent.clear":
                CheckAgentClear(data, frame.Type);
                break;
            case "session.resume":
                CheckSessionResume(data, frame.Type);
                break;
            case "pong":
                CheckPong(data, frame.Type);
                break;
        }
        return data;
    }

    /// <summary>The JSON text to send for a frame.</summary>
    public static string EncodeToString(Frame frame) => Encode(frame).ToJsonString(Options);

    private static T Build<T>(JsonObject obj)
        where T : Frame
    {
        try
        {
            return obj.Deserialize<T>(Options)!;
        }
        catch (JsonException error)
        {
            throw new FrameException($"{typeof(T).Name}: {error.Message}");
        }
    }

    private static string? StringOf(JsonNode? node) =>
        node is JsonValue value && value.TryGetValue<string>(out var s) ? s : null;

    private static long? IntegerOf(JsonNode? node)
    {
        if (node is not JsonValue value)
            return null;
        if (value.TryGetValue<long>(out var l))
            return l;
        if (value.TryGetValue<int>(out var i))
            return i;
        // A JSON number such as 1.0 or 1e3 is an integer when it has no fraction.
        if (value.TryGetValue<double>(out var d) && !double.IsNaN(d) && Math.Floor(d) == d && Math.Abs(d) < 9007199254740992d)
            return (long)d;
        return null;
    }

    private static double? NumberOf(JsonNode? node)
    {
        if (node is not JsonValue value)
            return null;
        if (value.TryGetValue<double>(out var d))
            return d;
        if (value.TryGetValue<long>(out var l))
            return l;
        if (value.TryGetValue<int>(out var i))
            return i;
        return null;
    }

    private static bool? BoolOf(JsonNode? node) =>
        node is JsonValue value && value.TryGetValue<bool>(out var b) ? b : null;

    internal static void CheckParty(JsonNode? d, string path = "Party")
    {
        if (d is not JsonObject) throw new FrameException(path + @" must be an object");
        if (!((d) as JsonObject)!.ContainsKey("kind")) throw new FrameException(path + @".kind is required");
        if (((d) as JsonObject)!.ContainsKey("kind"))
        {
            if (!(StringOf(((d) as JsonObject)!["kind"]) is string s1 && (s1 is ("user" or "number" or "conference" or "agent" or "anonymous") || Regex.IsMatch(s1, @"^[a-z][a-z0-9_]*$")))) throw new FrameException(path + ".kind" + @" is not an allowed value");
        }
        if (((d) as JsonObject)!.ContainsKey("value"))
        {
            if (StringOf(((d) as JsonObject)!["value"]) is not string) throw new FrameException(path + ".value" + @" must be a string");
