        {
            if (((d) as JsonObject)!["arguments"] is not JsonObject) throw new FrameException(path + ".arguments" + @" must be an object");
        }
        if (StringOf(((d) as JsonObject)!["name"]) == "transfer")
        {
            if (d is not JsonObject) throw new FrameException(path + @" must be an object");
            if (!((d) as JsonObject)!.ContainsKey("arguments")) throw new FrameException(path + @".arguments is required");
            if (((d) as JsonObject)!.ContainsKey("arguments"))
            {
                if (((d) as JsonObject)!["arguments"] is not JsonObject) throw new FrameException(path + ".arguments" + @" must be an object");
                if (!((((d) as JsonObject)!["arguments"]) as JsonObject)!.ContainsKey("to")) throw new FrameException(path + ".arguments" + @".to is required");
                if (((((d) as JsonObject)!["arguments"]) as JsonObject)!.ContainsKey("to"))
                {
                    CheckParty(((((d) as JsonObject)!["arguments"]) as JsonObject)!["to"], path + ".arguments" + ".to");
                    if (((((d) as JsonObject)!["arguments"]) as JsonObject)!["to"] is not JsonObject) throw new FrameException(path + ".arguments" + ".to" + @" must be an object");
                    if (((((((d) as JsonObject)!["arguments"]) as JsonObject)!["to"]) as JsonObject)!.ContainsKey("kind"))
                    {
                        if (StringOf(((((((d) as JsonObject)!["arguments"]) as JsonObject)!["to"]) as JsonObject)!["kind"]) is not ("user" or "number" or "agent")) throw new FrameException(path + ".arguments" + ".to" + ".kind" + @" is not one of the allowed values");
                    }
                }
            }
        }
        else if (StringOf(((d) as JsonObject)!["name"]) == "hangup")
        {
            if (d is not JsonObject) throw new FrameException(path + @" must be an object");
            if (((d) as JsonObject)!.ContainsKey("arguments"))
            {
                if (((d) as JsonObject)!["arguments"] is not JsonObject) throw new FrameException(path + ".arguments" + @" must be an object");
            }
        }
        else if (StringOf(((d) as JsonObject)!["name"]) == "send_dtmf")
        {
            if (d is not JsonObject) throw new FrameException(path + @" must be an object");
            if (!((d) as JsonObject)!.ContainsKey("arguments")) throw new FrameException(path + @".arguments is required");
            if (((d) as JsonObject)!.ContainsKey("arguments"))
            {
                if (((d) as JsonObject)!["arguments"] is not JsonObject) throw new FrameException(path + ".arguments" + @" must be an object");
                if (!((((d) as JsonObject)!["arguments"]) as JsonObject)!.ContainsKey("digits")) throw new FrameException(path + ".arguments" + @".digits is required");
                if (((((d) as JsonObject)!["arguments"]) as JsonObject)!.ContainsKey("digits"))
                {
                    if (StringOf(((((d) as JsonObject)!["arguments"]) as JsonObject)!["digits"]) is not string) throw new FrameException(path + ".arguments" + ".digits" + @" must be a string");
                    if (!Regex.IsMatch(StringOf(((((d) as JsonObject)!["arguments"]) as JsonObject)!["digits"])!, @"^[0-9*#A-Dw]+$")) throw new FrameException(path + ".arguments" + ".digits" + @" does not match ^[0-9*#A-Dw]+$");
                }
            }
        }
        else if (StringOf(((d) as JsonObject)!["name"]) == "hold")
        {
            if (d is not JsonObject) throw new FrameException(path + @" must be an object");
            if (!((d) as JsonObject)!.ContainsKey("arguments")) throw new FrameException(path + @".arguments is required");
            if (((d) as JsonObject)!.ContainsKey("arguments"))
            {
                if (((d) as JsonObject)!["arguments"] is not JsonObject) throw new FrameException(path + ".arguments" + @" must be an object");
                if (!((((d) as JsonObject)!["arguments"]) as JsonObject)!.ContainsKey("held")) throw new FrameException(path + ".arguments" + @".held is required");
                if (((((d) as JsonObject)!["arguments"]) as JsonObject)!.ContainsKey("held"))
                {
                    if (BoolOf(((((d) as JsonObject)!["arguments"]) as JsonObject)!["held"]) is not bool) throw new FrameException(path + ".arguments" + ".held" + @" must be true or false");
                }
            }
        }
        else
        {
            if (d is not JsonObject) throw new FrameException(path + @" must be an object");
            if (((d) as JsonObject)!.ContainsKey("arguments"))
            {
                if (((d) as JsonObject)!["arguments"] is not JsonObject) throw new FrameException(path + ".arguments" + @" must be an object");
            }
        }
    }

    internal static void CheckAgentClear(JsonNode? d, string path = "AgentClear")
    {
        if (d is not JsonObject) throw new FrameException(path + @" must be an object");
        if (!((d) as JsonObject)!.ContainsKey("session_id")) throw new FrameException(path + @".session_id is required");
        if (((d) as JsonObject)!.ContainsKey("session_id"))
        {
            if (StringOf(((d) as JsonObject)!["session_id"]) is not string) throw new FrameException(path + ".session_id" + @" must be a string");
            if (!Regex.IsMatch(StringOf(((d) as JsonObject)!["session_id"])!, @"^vs_[A-Za-z0-9-]+$")) throw new FrameException(path + ".session_id" + @" does not match ^vs_[A-Za-z0-9-]+$");
        }
    }

    internal static void CheckSessionResume(JsonNode? d, string path = "SessionResume")
    {
        if (d is not JsonObject) throw new FrameException(path + @" must be an object");
        if (!((d) as JsonObject)!.ContainsKey("session_id")) throw new FrameException(path + @".session_id is required");
        if (!((d) as JsonObject)!.ContainsKey("token")) throw new FrameException(path + @".token is required");
        if (!((d) as JsonObject)!.ContainsKey("received")) throw new FrameException(path + @".received is required");
        if (((d) as JsonObject)!.ContainsKey("session_id"))
        {
            if (StringOf(((d) as JsonObject)!["session_id"]) is not string) throw new FrameException(path + ".session_id" + @" must be a string");
            if (!Regex.IsMatch(StringOf(((d) as JsonObject)!["session_id"])!, @"^vs_[A-Za-z0-9-]+$")) throw new FrameException(path + ".session_id" + @" does not match ^vs_[A-Za-z0-9-]+$");
        }
        if (((d) as JsonObject)!.ContainsKey("token"))
        {
            if (StringOf(((d) as JsonObject)!["token"]) is not string) throw new FrameException(path + ".token" + @" must be a string");
            if (!Regex.IsMatch(StringOf(((d) as JsonObject)!["token"])!, @"^vsr_[A-Za-z0-9_-]+$")) throw new FrameException(path + ".token" + @" does not match ^vsr_[A-Za-z0-9_-]+$");
            if (StringOf(((d) as JsonObject)!["token"])!.Length < 26) throw new FrameException(path + ".token" + @" is shorter than 26");
            if (StringOf(((d) as JsonObject)!["token"])!.Length > 512) throw new FrameException(path + ".token" + @" is longer than 512");
        }
        if (((d) as JsonObject)!.ContainsKey("received"))
        {
            if (IntegerOf(((d) as JsonObject)!["received"]) is not long) throw new FrameException(path + ".received" + @" must be an integer");
            if (IntegerOf(((d) as JsonObject)!["received"]) < 0) throw new FrameException(path + ".received" + @" is below 0");
        }
    }

    internal static void CheckPong(JsonNode? d, string path = "Pong")
    {
        if (d is not JsonObject) throw new FrameException(path + @" must be an object");
