        if (((d) as JsonObject)!.ContainsKey("ts"))
        {
            if (IntegerOf(((d) as JsonObject)!["ts"]) is not long) throw new FrameException(path + ".ts" + @" must be an integer");
            if (IntegerOf(((d) as JsonObject)!["ts"]) < 0) throw new FrameException(path + ".ts" + @" is below 0");
        }
    }
